insert into public.curriculum_lessons(code,block_number,position,title,mission,skill_code,is_published) values('4.2',4,2,'Elige cómo reparar','Elige la aclaración o relectura que resuelve una duda concreta.','repair_choice',true);
insert into public.curriculum_lessons(code,block_number,position,title,mission,skill_code,is_published) values('4.3',4,3,'Vuelve con un propósito','Localiza el fragmento que responde tu pregunta.','targeted_reread',true);
insert into public.curriculum_lessons(code,block_number,position,title,mission,skill_code,is_published) values('4.4',4,4,'Recupera el foco','Retoma la última idea y el siguiente objetivo tras una pausa.','focus_resume',true);
do $seed$
declare item jsonb; cid uuid;
begin
 for item in select value from jsonb_array_elements($cases$[{"code":"4.2","v":"A","s":1,"r":"probe","p":"El aviso dice que la visita será el jueves, pero al final pide llegar el viernes. Necesitas reservar transporte.","q":"¿Cuál es la reparación más útil?","o":["Releer solo la fecha conflictiva y pedir confirmación","Volver a leer todo muchas veces sin objetivo","Elegir jueves por intuición"],"k":0},{"code":"4.2","v":"A","s":2,"r":"probe","p":"Elena envió el informe a Laura. Ella pidió una corrección mientras Elena llamaba al equipo.","q":"Si dudas de quién pidió la corrección, ¿qué debes revisar?","o":["La hora de la llamada","La oración que presenta a Laura y la acción siguiente","El título del informe"],"k":1},{"code":"4.2","v":"A","s":3,"r":"guided","p":"El anuncio ofrece una prórroga, pero no indica su duración. Necesitas entregar un formulario mañana.","q":"¿Qué acción resuelve el dato faltante?","o":["Suponer que la prórroga dura una semana","Ignorar el formulario","Consultar la fecha límite exacta"],"k":2},{"code":"4.2","v":"A","s":4,"r":"guided","p":"El puente aparece como cerrado en el primer párrafo. El segundo propone una ruta por él sin mencionar reapertura.","q":"¿Qué harías antes de elegir esa ruta?","o":["Verificar si se reabrió; releer no crea un dato ausente","Concluir que está abierto por aparecer en la ruta","Leer solo el nombre del puente"],"k":0},{"code":"4.2","v":"A","s":5,"r":"transfer","p":"Un texto dice: «El cupo total es veinte; quedan ocho lugares». Te parece contradictorio.","q":"¿Qué reparación mínima basta?","o":["Pedir al autor el cupo real","Distinguir total de disponibles y continuar","Cambiar ocho por veinte"],"k":1},{"code":"4.2","v":"A","s":6,"r":"transfer","p":"La instrucción usa «vigente», pero no especifica desde cuándo se acepta un documento. Tienes uno antiguo.","q":"¿Qué acción es más pertinente?","o":["Leer más rápido el mismo renglón","Adivinar la fecha","Consultar el periodo aceptado antes de actuar"],"k":2},{"code":"4.2","v":"B","s":1,"r":"probe","p":"El cartel anuncia un taller el martes y el formulario señala miércoles. Debes pedir permiso en el trabajo.","q":"¿Cómo reparas la contradicción?","o":["Comparar las dos fechas y confirmar con el organizador","Elegir la fecha del cartel sin verificar","Releer la misma palabra hasta recordar"],"k":0},{"code":"4.2","v":"B","s":2,"r":"probe","p":"Raúl dejó la llave con Marcos. Él abrió la sala mientras Raúl esperaba fuera.","q":"¿Qué fragmento releerías para resolver «él»?","o":["El horario de la sala","La entrega de la llave y la acción de abrir","La descripción del edificio"],"k":1},{"code":"4.2","v":"B","s":3,"r":"guided","p":"La tarifa tiene descuento, pero el aviso no dice a quién aplica. Necesitas pagar hoy.","q":"¿Qué corresponde hacer?","o":["Suponer que todos lo tienen","Cancelar sin preguntar","Consultar la condición de elegibilidad"],"k":2},{"code":"4.2","v":"B","s":4,"r":"guided","p":"El local figura como cerrado los domingos. Otro renglón propone recoger allí un pedido el domingo, sin excepción.","q":"¿Qué paso repara la duda para tu decisión?","o":["Confirmar si hay una excepción en el horario","Asumir que siempre abrirá","Ignorar el aviso de cierre"],"k":0},{"code":"4.2","v":"B","s":5,"r":"transfer","p":"Hay treinta sillas y dieciocho están ocupadas. Te parece imposible.","q":"¿Qué lectura basta?","o":["Pedir un recuento nuevo","Distinguir capacidad y ocupación","Sustituir treinta por dieciocho"],"k":1},{"code":"4.2","v":"B","s":6,"r":"transfer","p":"El mensaje promete una entrega «próxima», pero debes estar en casa a una hora concreta.","q":"¿Qué debes obtener?","o":["Una inferencia sobre el color del paquete","Otra lectura idéntica","Un horario preciso de entrega"],"k":2},{"code":"4.2","v":"C","s":1,"r":"probe","p":"Una nota dice que las inscripciones terminan el lunes; otra línea dice que cierran el martes. Necesitas inscribirte.","q":"¿Qué reparación procede?","o":["Verificar con la fuente el plazo vigente","Elegir martes por ser posterior","Releer sin comparar las líneas"],"k":0},{"code":"4.2","v":"C","s":2,"r":"probe","p":"Julia mostró el plano a Nora. Ella marcó la salida mientras Julia tomó notas.","q":"Si pierdes el referente, ¿qué debes volver a mirar?","o":["El color del plano","Las dos acciones y sus sujetos cercanos","La fecha del dibujo"],"k":1},{"code":"4.2","v":"C","s":3,"r":"guided","p":"Se ofrece entrada gratuita «bajo ciertas condiciones», que no aparecen. Quieres asistir.","q":"¿Qué acción resuelve la duda?","o":["Suponer que aplica a todos","No volver al evento","Consultar las condiciones reales"],"k":2},{"code":"4.2","v":"C","s":4,"r":"guided","p":"Un mapa marca la calle como bloqueada. La guía sugiere circular por ella sin explicar un cambio.","q":"¿Qué verificación necesitas?","o":["Comprobar el estado actual de la calle","Suponer que el mapa está mal","Volver a leer la palabra calle"],"k":0},{"code":"4.2","v":"C","s":5,"r":"transfer","p":"La sala tiene cuarenta lugares y quedan veinte libres. Dudas si puede ser cierto.","q":"¿Cuál es la reparación más breve?","o":["Pedir otro edificio","Separar capacidad total de lugares libres","Cambiar el número de libres"],"k":1},{"code":"4.2","v":"C","s":6,"r":"transfer","p":"La política acepta documentos «recientes», pero necesitas saber si uno de hace seis meses sirve.","q":"¿Qué precisión debes pedir?","o":["La tipografía del documento","La fecha de redacción de la política","El periodo exacto que consideran reciente"],"k":2},{"code":"4.3","v":"A","s":1,"r":"probe","p":"AVISO: La biblioteca abre de lunes a viernes de 9 a 18. Los sábados abre de 10 a 14. Los préstamos se suspenden una hora antes de cerrar.","q":"Quieres pedir un libro el sábado. ¿Qué datos debes releer?","o":["Horario del sábado y suspensión de préstamos","Horario del lunes únicamente","Nombre de la biblioteca"],"k":0},{"code":"4.3","v":"A","s":2,"r":"probe","p":"RESERVA: El cambio puede solicitarse hasta el miércoles anterior a las 17:00, si existe otro turno. La visita será el sábado.","q":"¿Qué fragmento verifica el plazo de cambio?","o":["El día de la visita","Hasta el miércoles anterior a las 17:00","La existencia de la sala"],"k":1},{"code":"4.3","v":"A","s":3,"r":"guided","p":"ENTREGA: Los pedidos del centro se recogen en recepción. Los pedidos de la zona norte se entregan en la entrada B. Se requiere mostrar folio.","q":"Si tu pedido es de zona norte, ¿qué parte buscas?","o":["Solo el requisito de folio","La ubicación de recepción","La línea que asigna la entrada B a zona norte"],"k":2},{"code":"4.3","v":"A","s":4,"r":"guided","p":"CURSO: Para asistir hay que registrarse antes del martes. La primera clase es el jueves. El material se entrega al entrar.","q":"¿Qué dato localizas para decidir si aún puedes inscribirte?","o":["La fecha límite del registro","La entrega del material","El día de la clase únicamente"],"k":0},{"code":"4.3","v":"A","s":5,"r":"transfer","p":"EL TURNO: Las citas del viernes se confirman el jueves a mediodía. Si no hay confirmación, el lugar pasa a otra persona.","q":"¿Qué fragmento justifica que debes confirmar?","o":["El nombre de otra persona","La condición de perder el lugar sin confirmación","La palabra viernes aislada"],"k":1},{"code":"4.3","v":"A","s":6,"r":"transfer","p":"REPARACIÓN: Los reportes sobre lámparas se envían al área de mantenimiento. Los de facturación se envían a administración.","q":"Para una lámpara dañada, ¿qué buscas?","o":["El área de facturación","La fecha de envío","La línea que asocia lámparas con mantenimiento"],"k":2},{"code":"4.3","v":"B","s":1,"r":"probe","p":"TRANSPORTE: La ruta A pasa cada 20 minutos hasta las 19:00. La ruta B termina a las 17:30. Ambas paran frente al hospital.","q":"Llegas a las 18:00. ¿Qué datos relees?","o":["Último horario de cada ruta","Nombre del hospital solamente","Frecuencia de la ruta B solamente"],"k":0},{"code":"4.3","v":"B","s":2,"r":"probe","p":"TALLER: Las cancelaciones se aceptan hasta el lunes a las 15:00. Las inscripciones cierran el miércoles.","q":"¿Qué línea verifica si puedes cancelar el martes?","o":["Cierre de inscripciones","Plazo de cancelación del lunes","Nombre del taller"],"k":1},{"code":"4.3","v":"B","s":3,"r":"guided","p":"DOCUMENTOS: Se aceptan copias para la consulta. Para el trámite final se requieren originales y firma.","q":"Quieres completar el trámite final. ¿Dónde buscas?","o":["En el requisito de la consulta","En la definición de copia","En la línea de originales y firma"],"k":2},{"code":"4.3","v":"B","s":4,"r":"guided","p":"MERCADO: Los puestos abren a las 8:00; los productos frescos llegan a las 10:00. El cobro termina a las 16:00.","q":"Quieres comprar productos frescos a las 9:00. ¿Qué dato necesitas?","o":["Hora de llegada de los productos frescos","Hora de cierre del cobro","Apertura de los puestos únicamente"],"k":0},{"code":"4.3","v":"B","s":5,"r":"transfer","p":"SALA: Se permite reservar hasta el viernes; la entrada se abre media hora antes de la función del domingo.","q":"¿Qué detalle determina cuándo reservar?","o":["Hora de la función","El límite del viernes","Apertura de la sala"],"k":1},{"code":"4.3","v":"B","s":6,"r":"transfer","p":"AVISO: Para cambiar un uniforme se necesita recibo. Para donarlo basta llevarlo limpio.","q":"Quieres donarlo. ¿Qué parte consultaras?","o":["El requisito del recibo","La regla para cambios","La condición de llevarlo limpio"],"k":2},{"code":"4.3","v":"C","s":1,"r":"probe","p":"PARQUE: La entrada norte abre de 7 a 18; la sur de 9 a 16. El estacionamiento cierra a las 17.","q":"Llegas caminando a las 8. ¿Qué datos comparas?","o":["Horarios de las dos entradas","Cierre del estacionamiento","Nombre del parque"],"k":0},{"code":"4.3","v":"C","s":2,"r":"probe","p":"ENVÍO: La dirección puede modificarse hasta las 12:00 del día anterior. El pedido sale a las 9:00 del día de entrega.","q":"¿Qué condición decide si cambiar la dirección?","o":["Hora de salida del pedido","Límite del día anterior a las 12:00","Fecha de fabricación"],"k":1},{"code":"4.3","v":"C","s":3,"r":"guided","p":"BIBLIOTECA: Los libros se devuelven en el buzón exterior durante el cierre. Las tabletas se entregan al personal en horario abierto.","q":"Debes devolver una tableta. ¿Qué fragmento buscas?","o":["La regla del buzón de libros","La palabra cierre","La entrega de tabletas al personal"],"k":2},{"code":"4.3","v":"C","s":4,"r":"guided","p":"CURSO: La prueba es el viernes. Quienes necesitan material adaptado deben pedirlo antes del martes.","q":"Necesitas material adaptado. ¿Qué fecha compruebas?","o":["El plazo del martes","La prueba del viernes únicamente","El día de inscripción de otros alumnos"],"k":0},{"code":"4.3","v":"C","s":5,"r":"transfer","p":"CLÍNICA: Los resultados se recogen personalmente los jueves. Se pueden solicitar copias digitales los lunes.","q":"Quieres recoger el original. ¿Qué dato relees?","o":["Lunes digital","Jueves presencial","La dirección del edificio"],"k":1},{"code":"4.3","v":"C","s":6,"r":"transfer","p":"CUENTA: Para corregir un cargo se envía el folio a facturación. Para cambiar la contraseña se usa el formulario de acceso.","q":"Quieres corregir un cargo. ¿Qué línea buscas?","o":["Formulario de acceso","Cambio de contraseña","Folio dirigido a facturación"],"k":2},{"code":"4.4","v":"A","s":1,"r":"probe","p":"Primero la asociación juntó libros. Después clasificó los títulos por edad. Ahora organiza una entrega a las familias.","q":"Tras una pausa, ¿cuál era la última acción completada?","o":["Clasificar los títulos","Entregar todos los libros","Abrir una escuela"],"k":0},{"code":"4.4","v":"A","s":2,"r":"probe","p":"El equipo comparó dos rutas. Una era corta pero tenía escaleras; la otra tardaba más y era accesible. Aún no ha decidido.","q":"¿Qué sigue pendiente al retomar?","o":["Medir las escaleras","Elegir la ruta","Comprar un autobús"],"k":1},{"code":"4.4","v":"A","s":3,"r":"guided","p":"La biblioteca amplió su horario de jueves. Se registraron más préstamos y luego se consideró añadir los martes.","q":"¿En qué punto retomas?","o":["Antes de abrir los jueves","Después de cerrar la biblioteca","En la decisión sobre añadir otro día"],"k":2},{"code":"4.4","v":"A","s":4,"r":"guided","p":"Una nota explica que el huerto perdió agua en verano. Los vecinos instalaron un depósito y ahora evaluarán su efecto.","q":"¿Qué pregunta guía la continuación?","o":["¿Funcionó el depósito para conservar agua?","¿Quién pintó el muro?","¿Cuál fue el precio de los libros?"],"k":0},{"code":"4.4","v":"A","s":5,"r":"transfer","p":"El mercado marcó precios por unidad. Tras un mes observó compras más rápidas; falta revisar si las etiquetas siguen legibles.","q":"¿Cuál es el próximo objetivo tras la pausa?","o":["Instalar otra caja","Verificar la legibilidad de las etiquetas","Repetir la primera oración de memoria"],"k":1},{"code":"4.4","v":"A","s":6,"r":"transfer","p":"El centro prestó tabletas. Aumentó la demanda y organizó reservas. Todavía no sabe si necesitará más equipos.","q":"¿Qué dato estaba pendiente?","o":["El nombre del centro","La fecha de apertura","Si hacen falta más tabletas"],"k":2},{"code":"4.4","v":"B","s":1,"r":"probe","p":"La escuela reunió uniformes. Los separó por talla. Ahora avisará a las familias para recogerlos.","q":"¿Cuál fue el último paso completado?","o":["Separarlos por talla","Entregarlos a todos","Comprar uniformes nuevos"],"k":0},{"code":"4.4","v":"B","s":2,"r":"probe","p":"La clínica probó recordar citas por mensaje. Menos personas faltaron, pero aún revisa cuánto cuesta el servicio.","q":"¿Qué asunto retomas?","o":["El nombre de los pacientes","El costo de mantener los mensajes","El horario de los autobuses"],"k":1},{"code":"4.4","v":"B","s":3,"r":"guided","p":"El barrio reparó el sendero y agregó señales. Ahora espera la primera lluvia para comprobar si funciona el drenaje.","q":"¿Dónde continúa la lectura?","o":["En la reparación inicial","En el diseño de señales","En la prueba del drenaje con lluvia"],"k":2},{"code":"4.4","v":"B","s":4,"r":"guided","p":"La cooperativa agrupó entregas por zona. Gastó menos combustible y planea medir si también mejoró la puntualidad.","q":"¿Qué pregunta queda al retomar?","o":["¿Mejoró la puntualidad?","¿Cuántas bancas hay?","¿Qué día nació la cooperativa?"],"k":0},{"code":"4.4","v":"B","s":5,"r":"transfer","p":"El museo ofreció audioguías. Los visitantes las usaron, aunque algunos no podían oír en ciertas salas.","q":"¿Qué aspecto conviene seguir?","o":["El precio de la pintura","La dificultad de audio en algunas salas","El origen de los visitantes"],"k":1},{"code":"4.4","v":"B","s":6,"r":"transfer","p":"La plaza ganó sombra con árboles nuevos. Más personas descansan allí; falta saber si el riego será suficiente en verano.","q":"¿Qué dato está pendiente?","o":["El tamaño del mercado","La fecha de la plaza","La suficiencia del riego estival"],"k":2},{"code":"4.4","v":"C","s":1,"r":"probe","p":"El hospital cambió la entrada de urgencias. Instaló señales nuevas. Ahora vigila si los pacientes llegan sin rodeos.","q":"¿Qué ya se completó antes de la pausa?","o":["Instalar las señales","Medir todos los recorridos","Cerrar urgencias"],"k":0},{"code":"4.4","v":"C","s":2,"r":"probe","p":"El taller compartió herramientas entre vecinos. Hubo más préstamos, pero aún debe decidir quién cubrirá las reparaciones.","q":"¿Qué cuestión sigue abierta?","o":["Cuántos vecinos existen","La responsabilidad por reparaciones","El color de las herramientas"],"k":1},{"code":"4.4","v":"C","s":3,"r":"guided","p":"El parque abrió una entrada adicional. Las visitas aumentaron. Ahora comprobarán si necesita más iluminación al anochecer.","q":"¿Cuál es el paso siguiente?","o":["Volver a construir la entrada","Contar árboles antiguos","Evaluar iluminación nocturna"],"k":2},{"code":"4.4","v":"C","s":4,"r":"guided","p":"La biblioteca reparó libros dañados. Regresaron a préstamo y luego se propuso ampliar el grupo de voluntarios.","q":"¿Qué decisión queda por estudiar?","o":["Ampliar el grupo de voluntarios","Cerrar préstamos","Cambiar todos los libros"],"k":0},{"code":"4.4","v":"C","s":5,"r":"transfer","p":"La escuela organizó transporte compartido. Se redujeron viajes individuales; falta evaluar los horarios de llegada.","q":"¿En qué te enfocas al retomar?","o":["La marca de los vehículos","La puntualidad de las llegadas","La cantidad de uniformes"],"k":1},{"code":"4.4","v":"C","s":6,"r":"transfer","p":"El centro registró las visitas de los sábados. Crecieron durante un mes; aún no sabe si se mantendrán en invierno.","q":"¿Qué evidencia falta?","o":["El número de empleados","La hora del primer sábado","La asistencia durante el invierno"],"k":2}]$cases$::jsonb) loop
  insert into public.curriculum_cases(lesson_code,content_version,variant,step,role,sentence,question,options)
   values(item->>'code',1,item->>'v',(item->>'s')::smallint,item->>'r',item->>'p',item->>'q',item->'o') returning id into cid;
  insert into private.curriculum_answer_keys(case_id,correct_index,feedback)
   select cid,(item->>'k')::smallint,(select jsonb_agg(case when i=(item->>'k')::integer then 'Bien. Elegiste la información precisa para continuar con sentido.' else 'Vuelve al objetivo: usa solo el dato que resuelve la duda.' end order by i) from generate_series(0,2) i);
  insert into private.curriculum_case_rubrics(case_id,error_codes,skill_code)
   select cid,(select jsonb_agg(case when i=(item->>'k')::integer then null else 'monitor_strategy_missed' end order by i) from generate_series(0,2) i),
    (select skill_code from public.curriculum_lessons where code=item->>'code');
 end loop;
end $seed$;
create or replace function private.begin_curriculum_lesson(p_lesson_code text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid(); l public.curriculum_lessons%rowtype;
 a public.curriculum_attempts%rowtype; completed_count integer; chosen_variant text;
begin
 if u is null then raise exception 'Inicia sesión para aprender.' using errcode='28000'; end if;
 if not private.can_practice() then raise exception 'Tu acceso al programa no está activo.' using errcode='42501'; end if;
 select * into l from public.curriculum_lessons where code=p_lesson_code and is_published;
 if not found then raise exception 'La misión no está disponible.' using errcode='22023'; end if;
 if p_lesson_code in ('1.2','1.3','1.4','1.C') and not exists
   (select 1 from public.curriculum_attempts where user_id=u and lesson_code=case p_lesson_code when '1.2' then '1.1' when '1.3' then '1.2' when '1.4' then '1.3' else '1.4' end and status='completed') then
   raise exception 'Completa la lección anterior primero.' using errcode='22023'; end if;
 if p_lesson_code='2.1' and not exists
   (select 1 from public.curriculum_attempts a0 where a0.user_id=u and a0.lesson_code='1.C' and a0.status='completed' and a0.transfer_correct>=5
    and (select count(distinct r.skill_code) from public.curriculum_responses r where r.attempt_id=a0.id and r.first_correct)=5) then
   raise exception 'Primero comprueba las habilidades del nivel 1.1.' using errcode='22023'; end if;
 if p_lesson_code in ('2.2','2.3','2.4','2.C') and not exists
   (select 1 from public.curriculum_attempts where user_id=u and lesson_code=case p_lesson_code when '2.2' then '2.1' when '2.3' then '2.2' when '2.4' then '2.3' else '2.4' end and status='completed') then
   raise exception 'Completa la lección anterior del nivel 1.2.' using errcode='22023'; end if;
 if p_lesson_code='3.1' and not exists
   (select 1 from public.curriculum_attempts a0 where a0.user_id=u and a0.lesson_code='2.C' and a0.status='completed' and a0.transfer_correct>=5
    and (select count(distinct r.skill_code) from public.curriculum_responses r where r.attempt_id=a0.id and r.first_correct)=4) then
   raise exception 'Primero comprueba las habilidades del nivel 1.2.' using errcode='22023'; end if;
 if p_lesson_code='4.1' and not exists
   (select 1 from public.curriculum_attempts a0 where a0.user_id=u and a0.lesson_code='3.C' and a0.status='completed' and a0.transfer_correct>=5
    and (select count(distinct r.skill_code) from public.curriculum_responses r where r.attempt_id=a0.id and r.first_correct)=4) then
   raise exception 'Primero comprueba las habilidades del nivel 1.3.' using errcode='22023'; end if;
 if p_lesson_code in ('3.2','3.3','3.4','3.C') and not exists
   (select 1 from public.curriculum_attempts where user_id=u and lesson_code=case p_lesson_code when '3.2' then '3.1' when '3.3' then '3.2' when '3.4' then '3.3' else '3.4' end and status='completed') then
   raise exception 'Completa la lección anterior del nivel 1.3.' using errcode='22023'; end if;
 if p_lesson_code in ('4.2','4.3','4.4') and not exists
   (select 1 from public.curriculum_attempts where user_id=u and lesson_code=case p_lesson_code when '4.2' then '4.1' when '4.3' then '4.2' else '4.3' end and status='completed') then
   raise exception 'Completa la lección anterior del nivel 1.4.' using errcode='22023'; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(u::text||':'||p_lesson_code, 0));
 select * into a from public.curriculum_attempts where user_id=u and lesson_code=l.code and status='active' for update;
 if not found then
   select count(*) into completed_count from public.curriculum_attempts where user_id=u and lesson_code=l.code and status='completed';
   chosen_variant := case when completed_count % 3 = 0 then 'A' when completed_count % 3 = 1 then 'B' else 'C' end;
   if (select count(*) from public.curriculum_cases where lesson_code=l.code and content_version=l.content_version and variant=chosen_variant) <> 6 then raise exception 'Faltan casos para esta misión.' using errcode='22023'; end if;
   insert into public.curriculum_attempts(user_id,lesson_code,content_version,variant) values(u,l.code,l.content_version,chosen_variant) returning * into a;
 end if;
 return private.curriculum_lesson_state(a.id);
end $$;
commit;
